-- 8bdf2100 | ما أدب طالب العلم مع شيخه؟
UPDATE qa_questions SET
  answer = 'أدبُ طالب العلم مع شيخه أربعةٌ نقل ابن عبد البر ألفاظها في جامع بيان العلم وفضله: (١) حسنُ السؤال — «حُسْنُ الْمَسْأَلَةِ نِصْفُ الْعِلْمِ، وَالرِّفْقُ نِصْفُ الْعَيْشِ» (ح٥٤٤، ج١/ص٣٨٢)، وبوَّب له بـ‹باب حمد السؤال والإلحاح في طلب العلم› فالسؤالُ عنده ممدوحٌ مطلوبٌ لا مذموم. (٢) والإنصاتُ — «أَوَّلُ الْعِلْمِ الِاسْتِمَاعُ، ثُمَّ الْإِنْصَاتُ، ثُمَّ الْحِفْظُ، ثُمَّ الْعَمَلُ، ثُمَّ النَّشْرُ» (سفيان، ح٧٦١، ج١/ص٤٧٧). (٣) والتوقيرُ والتواضعُ — «تَعَلَّمُوا الْعِلْمَ وَتَزَيَّنُوا مَعَهُ بِالْوَقَارِ وَالْحِلْمِ وَتَوَاضَعُوا لِمَنْ تَتَعَلَّمُونَ مِنْهُ وَلِمَنْ تُعَلِّمُونَهُ» (علي بن أبي طالب رضي الله عنه، ح٩٤١، ج١/ص٥٦١)، وقال ابن عباس رضي الله عنهما: «ذَلَلْتُ طَالِبًا فَعَزَزْتُ مَطْلُوبًا» (ح٧٥٦، ج١/ص٤٧٤). (٤) وتركُ المراء — وبوَّب له ابن عبد البر بـ«بَابُ مَا تُكْرَهُ فِيهِ الْمُنَاظَرَةُ وَالْجِدَالُ وَالْمِرَاءُ» ثم قيَّده تقييدًا مهمًّا فقال: «الْآثَارُ كُلُّهَا فِي هَذَا الْبَابِ الْمَرْوِيَّةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّمَا وَرَدَتْ فِي النَّهْيِ عَنِ الْجِدَالِ وَالْمِرَاءِ فِي الْقُرْآنِ»، «وَأَمَّا التَّنَازُعُ فِي أَحْكَامِ الْقُرْآنِ وَمَعَانِيهِ فَقَدْ تَنَازَعَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كَثِيرٍ مِنْ ذَلِكَ» (ج٢/ص٩٢٨) — فالمذمومُ الجحودُ والشكُّ والملاحاةُ، لا طلبُ الفهم ولا السؤالُ عن الدليل.',
  reference = 'جامع بيان العلم وفضله لابن عبد البر (ت أبي الأشبال الزهيري، دار ابن الجوزي بالسعودية، ط١ ١٤١٤هـ): ح٥٤٤، ج١/ص٣٨٢ (باب حمد السؤال والإلحاح في طلب العلم)، وح٧٥٦، ج١/ص٤٧٤، وح٧٦١، ج١/ص٤٧٧ (باب منازل العلماء)، وح٨٠٣، ج١/ص٥٠١ (باب جامع في آداب العالم والمتعلم)، وح٩٤١ وح٩٤٣، ج١/ص٥٦١، وج٢/ص٩٢٨ (باب ما تكره فيه المناظرة والجدال والمراء) | الكلمات المفتاحية: أدب، شيخ، علم',
  evidence = 'بوَّب ابن عبد البر لهذا الأدب أبوابًا ونقل فيها ألفاظ السلف بأعيانها. ففي حسن السؤال روى عن وهب بن منبه وسليمان بن يسار أنهما قالا: «حُسْنُ الْمَسْأَلَةِ نِصْفُ الْعِلْمِ، وَالرِّفْقُ نِصْفُ الْعَيْشِ» (ح٥٤٤، ج١/ص٣٨٢). وفي الإنصات قال سفيان: «أَوَّلُ الْعِلْمِ الِاسْتِمَاعُ، ثُمَّ الْإِنْصَاتُ، ثُمَّ الْحِفْظُ، ثُمَّ الْعَمَلُ، ثُمَّ النَّشْرُ» (ح٧٦١، ج١/ص٤٧٧). وفي التوقير والتواضع قال علي بن أبي طالب رضي الله عنه: «تَعَلَّمُوا الْعِلْمَ وَتَزَيَّنُوا مَعَهُ بِالْوَقَارِ وَالْحِلْمِ وَتَوَاضَعُوا لِمَنْ تَتَعَلَّمُونَ مِنْهُ وَلِمَنْ تُعَلِّمُونَهُ، وَلَا تَكُونُوا جَبَابِرَةَ الْعُلَمَاءِ فَيُذْهِبَ بَاطِلُكُمْ حَقَّكُمْ» (ح٩٤١، ج١/ص٥٦١)، وقال ابن عباس رضي الله عنهما: «ذَلَلْتُ طَالِبًا فَعَزَزْتُ مَطْلُوبًا» (ح٧٥٦، ج١/ص٤٧٤). وقال أبو عمر عقب أثر علي: «قَدْ رُوِيَ هَذَا الْمَعْنَى بِنَحْوِ هَذَا اللَّفْظِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ» (ح٩٤٣، ج١/ص٥٦١). وأصلُ حمد السؤال قولُه تعالى: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ﴾ [النحل: 43].',
  verification_status = 'verified'
WHERE id = '8bdf2100-928b-44b3-b683-618aefc6cc7f'
  AND reference = 'جامع بيان العلم وفضله | الكلمات المفتاحية: أدب، شيخ، علم'
  AND evidence = 'قال تعالى: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ﴾ [النحل: 43].'
  AND answer = 'من الأدب حسن السؤال والإنصات والتوقير وعدم التعجل في الاعتراض.';

-- 109a288c | ما معنى السياسة الشرعية؟
UPDATE qa_questions SET
  answer = 'السياسةُ الشرعية عند ابن تيمية مبنيّةٌ على أصلين نصَّت عليهما آيةُ الأمانة: «وإذا كانت الآية قد أوجبت أداء الأمانات إلى أهلها، والحكم بالعدل، فهذان جِماع السياسة العادلة، والولاية الصالحة» (ص٥). والأمانات عنده نوعان: «فصل أما أداء الأمانات ففيه نوعان: أحدهما: الولايات»، وثمرتُه: «فيجب على وليِّ الأمر أن يولِّي على كل عملٍ من أعمال المسلمين أصلح مَن يجده لذلك العمل» (ص٦). وأما الحكمُ بالعدل فمحلُّه «الحدود والحقوق» (ص٨٤). وحدَّها ابن القيم بأنها من الشرع لا خارجةٌ عنه: «تبين له أن السياسة العادلة جزء من أجزائها، وفرع من فروعها»، وقسَّمها قسمين: «فإن السياسة نوعان : سياسة ظالمة فالشريعة تحرمها،» «وسياسة عادلة تخرج الحق من الظالم الفاجر، فهي من الشريعة، عَلِمَها من عَلِمها، وجهلها من جهلها» (الطرق الحكمية، ج١/ص٧-٨). وضابطُ تصرُّف الوالي قاعدةٌ مستقلّة عند السيوطي عن الشافعي: «تَصَرُّفُ الْإِمَامِ عَلَى الرَّعِيَّةِ مَنُوطٌ بِالْمَصْلَحَةِ» (الأشباه والنظائر، ص١٢١).',
  reference = 'السياسة الشرعية في إصلاح الراعي والرعية لابن تيمية (ت علي بن محمد العمران، دار عطاءات العلم بالرياض ودار ابن حزم ببيروت، ط٤ ١٤٤٠هـ): ص٥-٦ (على ما بنيت الرسالة)، وص٨٤ (فصل في قوله تعالى وإذا حكمتم بين الناس)؛ الطرق الحكمية في السياسة الشرعية لابن القيم (ت نايف بن أحمد الحمد، دار عطاءات العلم، ط٤ ١٤٤٠هـ): ج١/ص٧-٨ (لا بد للحاكم من نوعين من الفقه)؛ الأشباه والنظائر للسيوطي (دار الكتب العلمية ببيروت، ط١ ١٤٠٣هـ/١٩٨٣م): ص١٢١ (القاعدة الخامسة: تصرف الإمام على الرعية منوط بالمصلحة) | الكلمات المفتاحية: سياسة شرعية، مصلحة، عدل',
  evidence = 'بنى ابن تيمية رسالته على آية الأمانة فقال بعد سياقها: «وإذا كانت الآية قد أوجبت أداء الأمانات إلى أهلها، والحكم بالعدل، فهذان جِماع السياسة العادلة، والولاية الصالحة» (السياسة الشرعية، ص٥). وقال ابن القيم: «تبين له أن السياسة العادلة جزء من أجزائها، وفرع من فروعها»، «فإن السياسة نوعان : سياسة ظالمة فالشريعة تحرمها،» «وسياسة عادلة تخرج الحق من الظالم الفاجر، فهي من الشريعة، عَلِمَها من عَلِمها، وجهلها من جهلها» (الطرق الحكمية، ج١/ص٧-٨). وأما «تصرف الإمام على الرعية منوط بالمصلحة» فقاعدةٌ فقهية أوردها السيوطي وقال: «هَذِهِ الْقَاعِدَةُ نَصَّ عَلَيْهَا الشَّافِعِيُّ وَقَالَ " مَنْزِلَةَ الْإِمَامِ مِنْ الرَّعِيَّةِ مَنْزِلَة الْوَلِيِّ مِنْ الْيَتِيمِ "» (الأشباه والنظائر، ص١٢١) — فهي للسيوطي عن الشافعي لا لابن تيمية.',
  verification_status = 'verified'
WHERE id = '109a288c-231f-4df7-93d9-75bef2445be5'
  AND reference = 'السياسة الشرعية لابن تيمية | الكلمات المفتاحية: سياسة شرعية، مصلحة، عدل'
  AND evidence = 'تصرف الإمام على الرعية منوط بالمصلحة بضوابط الشرع.'
  AND answer = 'رعاية شؤون الناس بما يحقق العدل والمصلحة المعتبرة دون مخالفة النصوص.';

-- 7295fbea | هل يجوز نقض حكم القاضي إذا تبيّن خطؤه؟
UPDATE qa_questions SET
  answer = 'المسألةُ محرَّرةٌ في المغني بحدِّها: «(وَلَا يَنْقُضُ مِنْ حُكْمِ غَيْرِهِ إذَا رُفِعَ إلَيْهِ، إلَّا مَا خالَفَ نصَّ كِتَابٍ، أوْ سُنَّةٍ، أوْ إِجْمَاعًا)» — «فإن كان الخطأُ لِمُخالفةِ نَصِّ كتابٍ أو سنَّةٍ أو إجْماعٍ، نَقَضَ حُكْمَه»؛ وعلّتُه: «أنَّه قَضاءٌ لم يُصادِفْ شَرْطَه»، «أنَّ شرطَ الحُكْمِ بالاجْتهادِ عَدمُ النَّصِّ» (ج١٤/ص٣٤). وليست المسألةُ محلَّ اتفاقٍ في حدِّها: «وبهذا قال الشَّافعىُّ، وزادَ: إذا خالفَ قِياسًا جَلِيًّا نَقَضَه. وعن مالكٍ، وأبى حنيفةَ، أنَّهما قالا: لا يَنْقُضُ الحُكْمَ إلَّا إذا خالفَ الإجْماعَ»، وحُكي عن أبي ثور وداود «أنَّه يَنْقُضُ جميعَ ما بانَ له خَطؤُه» لكتاب عمر رضي الله عنه إلى أبي موسى: «لا يَمْنَعنَّك قَضاءٌ قَضَيْتَه بالأمْسِ، ثم رَاجَعْتَ نفسَك فيه اليومَ، فهُدِيتَ لرُشْدِكَ ، أن تُراجِعَ فيه الحقَّ؛ فإنَّ الرجوعَ إلى الحقِّ خيرٌ من التَّمادِى فى الباطلِ». وأما ما كان اجتهادًا سائغًا فلا يُنقَض، وقاعدتُه عند السيوطي: «الِاجْتِهَادُ لَا يُنْقَضُ بِالِاجْتِهَادِ»، وأصلُها «إجْمَاعُ الصَّحَابَةِ رَضِيَ اللَّهُ عَنْهُمْ»، وعلّتُها: «أَنَّهُ لَيْسَ الِاجْتِهَادُ الثَّانِي بِأَقْوَى مِنْ الْأَوَّلِ فَإِنَّهُ يُؤَدِّي إلَى أَنَّهُ لَا يَسْتَقِرُّ حُكْمٌ» (الأشباه والنظائر، ص١٠١).',
  reference = 'المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب): ج١٤/ص٣٤ (مسألة ١٨٦٨: ولا ينقض من حكم غيره إذا رفع إليه إلا ما خالف نص كتاب أو سنة أو إجماعا)؛ الأشباه والنظائر للسيوطي (دار الكتب العلمية ببيروت، ط١ ١٤٠٣هـ/١٩٨٣م): ص١٠١ (القاعدة الأولى: الاجتهاد لا ينقض بالاجتهاد) | الكلمات المفتاحية: نقض الحكم، القضاء، اجتهاد القاضي',
  evidence = 'قال ابن قدامة: «(وَلَا يَنْقُضُ مِنْ حُكْمِ غَيْرِهِ إذَا رُفِعَ إلَيْهِ، إلَّا مَا خالَفَ نصَّ كِتَابٍ، أوْ سُنَّةٍ، أوْ إِجْمَاعًا)»، ثم قال: «وجملةُ ذلك أنَّ الحاكمَ إذا رُفعَتْ إليه قَضِيَّةٌ قد قضَى بها حاكمٌ سِواهُ، فبانَ له خَطؤُه، أو بانَ له خطأُ نَفْسِه، نَظَرْتَ؛ فإن كان الخطأُ لِمُخالفةِ نَصِّ كتابٍ أو سنَّةٍ أو إجْماعٍ، نَقَضَ حُكْمَه. وبهذا قال الشَّافعىُّ، وزادَ: إذا خالفَ قِياسًا جَلِيًّا نَقَضَه» (المغني، ج١٤/ص٣٤). وقال السيوطي: «الْقَاعِدَةُ الْأُولَى الِاجْتِهَادُ لَا يُنْقَضُ بِالِاجْتِهَادِ الْأَصْلُ فِي ذَلِكَ إجْمَاعُ الصَّحَابَةِ رَضِيَ اللَّهُ عَنْهُمْ» (الأشباه والنظائر، ص١٠١).',
  verification_status = 'verified'
WHERE id = '7295fbea-e501-4f9d-8d16-e97c3dcf7a73'
  AND reference = 'قواعد القضاء في الفقه الإسلامي | الكلمات المفتاحية: نقض الحكم، القضاء، اجتهاد القاضي'
  AND evidence = 'قاعدة فقهية مستقرة: اجتهاد القاضي لا يُنقض إلا بمخالفة نص أو إجماع'
  AND answer = 'إذا تبيّن أن القاضي حكم بخلاف نص شرعي صريح أو إجماع أو خالف قواعد العدل الظاهرة فإن حكمه يُنقض، أما إذا كان اجتهادًا سائغًا يحتمل الخلاف بين الفقهاء فلا يُنقض، لأن اجتهاد القاضي مبني على غالب ظنه لا على علم الغيب.';

-- 6e93f78a | من هو عمر بن عبد العزيز، ولماذا يُلقَّب بخامس الخلفاء الراشدين؟
UPDATE qa_questions SET
  answer = 'عمر بن عبد العزيز خليفة أموي زاهد عادل، تولى الخلافة سنة 99هـ فأعاد الحقوق المغصوبة وألغى سبّ علي بن أبي طالب على المنابر ووسّع رقعة العدل، فاستحق عند كثير من العلماء لقب "خامس الخلفاء الراشدين" تشبيهًا بسيرة الخلفاء الأربعة الأوائل رغم عدم كونه منهم زمنيًا. وموضعُ ذلك من سير أعلام النبلاء: بويع له بعد وفاة سليمان بن عبد الملك — «ثُمَّ كُفِّنَ سُلَيْمَانُ فِي عَاشِرِ صَفَرٍ، سَنَةَ تِسْعٍ وَتِسْعِيْنَ، وَصَلَّى عَلَيْهِ: عُمَرُ بنُ عَبْدِ العَزِيْزِ» (ج٥/ص١١٣) — «وَكَانَتْ خِلاَفَتُهُ سَنَتَيْنِ وَخَمْسَةَ أَشْهُرٍ وَأَيَّاماً» (ج٥/ص١٤٥). واللقبُ ليس دعوى متأخِّرة، بل قولُ أئمّة: «الخُلَفَاءُ خَمْسَةٌ: أَبُو بَكْرٍ، وَعُمَرُ، وَعُثْمَانُ، وَعلِيُّ، وَعُمَرُ بنُ عَبْدِ العَزِيْزِ» (الشافعي، ج١٠/ص٢٠)، «وَوَرَدَ عَنْ أَبِي بَكْرٍ بنِ عَيَّاشٍ نَحْوَهُ. وَرَوَى: عَبَّادُ بنُ السَّمَّاكِ، عَنِ الثَّوْرِيِّ، مِثْلَهُ» (ج٥/ص١٣١). وأثرُ عدله في الناس: «قَدْ أَغْنَى عُمَرُ النَّاسَ» (ج٥/ص١٣١)، وزهدُه في نفسه: «كَمْ كَانَتْ غَلَّةُ عُمَرَ بنِ عَبْدِ العَزِيْزِ حِيْنَ اسْتُخْلِفَ؟ قُلْتُ: خَمْسُوْنَ أَلْفَ دِيْنَارٍ. قَالَ: كَمْ كَانَتْ يَوْمَ مَوْتِهِ؟ قُلْتُ: مائَتَا دِيْنَارٍ» (ج٥/ص١٣٤). ولم يُطلق السلفُ فيه القولَ بلا قيد؛ قال طاووس لما سُئل أهو المهدي: «هُوَ المَهْدِيُّ، وَلَيْسَ بِهِ، إِنَّهُ لَمْ يَسْتَكْمِلِ العَدْلَ كُلَّهُ» (ج٥/ص١٣٠).',
  reference = 'سير أعلام النبلاء للذهبي (بإشراف شعيب الأرناؤوط، مؤسسة الرسالة، ط٣ ١٤٠٥هـ): ج٥/ص١١٣-١١٤ و١٣٠-١٣١ و١٣٤ و١٤٥ (ترجمة عمر بن عبد العزيز)، وج١٠/ص٢٠ (ترجمة الشافعي) | الكلمات المفتاحية: عمر بن عبد العزيز، خامس الخلفاء الراشدين',
  evidence = 'قال الذهبي في ترجمته: «الإِمَامُ، الحَافِظُ، العَلاَّمَةُ، المُجْتَهِدُ، الزَّاهِدُ، العَابِدُ، السَّيِّدُ، أَمِيْرُ المُؤْمِنِيْنَ حَقّاً، أَبُو حَفْصٍ القُرَشِيُّ»، «وَكَانَ مِنْ أَئِمَّةِ الاجْتِهَادِ، وَمِنَ الخُلَفَاءِ الرَّاشِدِيْنَ» (ج٥/ص١١٤). وأصلُ لقب الخامس قولُ الشافعي: «سَمِعْتُ الشَّافِعِيَّ يَقُوْلُ: الخُلَفَاءُ خَمْسَةٌ: أَبُو بَكْرٍ، وَعُمَرُ، وَعُثْمَانُ، وَعلِيُّ، وَعُمَرُ بنُ عَبْدِ العَزِيْزِ» (ج١٠/ص٢٠)، وأعاده الذهبي في ترجمة عمر وزاد: «وَفِي رِوَايَةٍ: الخُلَفَاءُ الرَّاشِدُوْنَ. وَوَرَدَ عَنْ أَبِي بَكْرٍ بنِ عَيَّاشٍ نَحْوَهُ. وَرَوَى: عَبَّادُ بنُ السَّمَّاكِ، عَنِ الثَّوْرِيِّ، مِثْلَهُ» (ج٥/ص١٣١). وولايتُه بعد سليمان: «ثُمَّ كُفِّنَ سُلَيْمَانُ فِي عَاشِرِ صَفَرٍ، سَنَةَ تِسْعٍ وَتِسْعِيْنَ، وَصَلَّى عَلَيْهِ: عُمَرُ بنُ عَبْدِ العَزِيْزِ» (ج٥/ص١١٣)، «وَكَانَتْ خِلاَفَتُهُ سَنَتَيْنِ وَخَمْسَةَ أَشْهُرٍ وَأَيَّاماً» (ج٥/ص١٤٥).',
  verification_status = 'verified'
